import random, itertools, time

def win(A,B):
    return sum(a>b for a in A for b in B)

def rand_die():
    return tuple(sorted(random.randrange(12) for _ in range(6)))

start=time.time()
best=0
bestdice=None
for t in range(2000000):
    dice=[rand_die() for _ in range(5)]
    ws=[win(dice[i], dice[(i+1)%5]) for i in range(5)]
    m=min(ws)
    if m>best:
        best=m; bestdice=(dice,ws); print('best', best, ws, dice, 't', t)
    if m>18:
        print('FOUND', ws, dice, 't',t); break
print('done', time.time()-start, 'best', bestdice)
